1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export interface InsuredItem {
11	  type: string;
12	  material?: string;
13	  enchantment?: number;
14	  cursed?: boolean;
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	/** A request to price a set of items. Becomes a policy the claims refer back to. */
28	export interface QuoteStep {
29	  op: "quote";
30	  items: InsuredItem[];
31	}
32	
33	/** A claim against an earlier quote step, identified by its index. */
34	export interface ClaimStep {
35	  op: "claim";
36	  policy: number;
37	  incident: Incident;
38	}
39	
40	/**
41	 * The two things a scenario can ask for. Discriminating on `op` lets the
42	 * compiler guarantee a claim has an incident and a quote has items, so
43	 * neither dispatch arm needs a non-null assertion or a defaulted field.
44	 */
45	export type Step = QuoteStep | ClaimStep;
46	
47	export interface QuoteResult {
48	  premium: number;
49	}
50	
51	export interface ClaimResult {
52	  payout: number;
53	  remainingCap: number;
54	}
55	
56	export type StepResult = QuoteResult | ClaimResult;
57	
58	export interface ScenarioResults {
59	  results: StepResult[];
60	}
61	
62	const BASE_PREMIUMS: Record<string, number> = {
63	  sword: 100,
64	  amulet: 60,
65	  staff: 80,
66	  potion: 40,
67	  rune: 25,
68	  moonstone: 25,
69	};
70	
71	const INSURANCE_VALUES: Record<string, number> = {
72	  sword: 1000,
73	  amulet: 600,
74	  staff: 800,
75	  potion: 400,
76	  rune: 250,
77	  moonstone: 250,
78	};
79	
80	const PROCESSING_FEE = 5;
81	
82	const WHOLE_PERCENT = 100;
83	
84	/**
85	 * Adjusts an amount by a percentage. A positive percent is a surcharge, a
86	 * negative one a discount.
87	 *
88	 * Multiplying before dividing keeps the arithmetic exact. A 1.1 multiplier
89	 * would not: floating-point `100 * 1.1` is 110.00000000000001, which rounds
90	 * up to 111 and yields a 116 G premium instead of 115 G.
91	 */
92	const adjustByPercent = (amount: number, percent: number): number =>
93	  (amount * (WHOLE_PERCENT + percent)) / WHOLE_PERCENT;
94	
95	/** All rounding is in the MHPCO's favor — always up. */
96	const roundInMHPCOsFavor = Math.ceil;
97	
98	const BUILDING_BLOCK_SIZE = 3;
99	const BUILDING_BLOCK_PREMIUM = 60;
100	
101	/** Item kinds are compared by type — both grouping and claims match on it. */
102	const isOfType =
103	  (type: string) =>
104	  (item: InsuredItem): boolean =>
105	    item.type === type;
106	
107	/** Only items of one and the same kind group into a block. */
108	const areAllTheSameKind = ([first, ...rest]: InsuredItem[]): boolean =>
109	  first !== undefined && rest.every(isOfType(first.type));
110	
111	/**
112	 * How many flat-rate blocks this list forms. A mixed list forms none — only
113	 * alike items group — and so does any list too short to fill one block.
114	 */
115	const countCompleteBlocks = (items: InsuredItem[]): number =>
116	  areAllTheSameKind(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;
117	
118	const CURSED_SURCHARGE_PERCENT = 50;
119	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
120	
121	/**
122	 * Enchantment drives two unrelated rules at two different levels, so each
123	 * threshold is named for the rule it belongs to rather than for the adjective
124	 * the spec happens to use. Level 5 makes an item dearer to insure; level 8
125	 * makes damage to it cheaper to reimburse. Neither level should ever be
126	 * substituted for the other.
127	 */
128	const SURCHARGEABLE_ENCHANTMENT_LEVEL = 5;
129	
130	/** A risk rule contributes its percent only when the item trips it. */
131	const percentWhen = (applies: boolean, percent: number): number =>
132	  applies ? percent : 0;
133	
134	const enchantmentOf = (item: InsuredItem): number => item.enchantment ?? 0;
135	
136	const attractsEnchantmentSurcharge = (item: InsuredItem): boolean =>
137	  enchantmentOf(item) >= SURCHARGEABLE_ENCHANTMENT_LEVEL;
138	
139	/** Risk surcharges add to the base premium; they do not compound. */
140	const riskSurchargePercentFor = (item: InsuredItem): number =>
141	  percentWhen(item.cursed === true, CURSED_SURCHARGE_PERCENT) +
142	  percentWhen(
143	    attractsEnchantmentSurcharge(item),
144	    HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
145	  );
146	
147	/** An item's list price with its own risk surcharges applied. */
148	const riskAdjustedPremiumFor = (item: InsuredItem): number =>
149	  adjustByPercent(BASE_PREMIUMS[item.type], riskSurchargePercentFor(item));
150	
151	/**
152	 * Prices an item list: alike items are grouped into building blocks sold at a
153	 * flat rate, and whatever is left over is priced item by item, each at its own
154	 * risk-adjusted premium.
155	 */
156	const priceItems = (items: InsuredItem[]): number => {
157	  const blocks = countCompleteBlocks(items);
158	  const leftovers = items.slice(blocks * BUILDING_BLOCK_SIZE);
159	
160	  return (
161	    blocks * BUILDING_BLOCK_PREMIUM +
162	    leftovers.reduce((sum, item) => sum + riskAdjustedPremiumFor(item), 0)
163	  );
164	};
165	
166	/** Discounts are negative adjustments — long-standing customers pay 20% less. */
167	const LOYALTY_DISCOUNT_PERCENT = -20;
168	const LOYALTY_YEARS = 2;
169	const REPEAT_CONTRACT_DISCOUNT_PERCENT = -15;
170	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
171	
172	const isLongStanding = (customer: Customer): boolean =>
173	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
174	
175	/** The first contract is assessed; every later one earns a discount instead. */
176	const contractPercentFor = (isFirstContract: boolean): number =>
177	  isFirstContract
178	    ? FIRST_INSURANCE_SURCHARGE_PERCENT
179	    : REPEAT_CONTRACT_DISCOUNT_PERCENT;
180	
181	/**
182	 * The customer's own standing modifies the item price. Unlike the risk
183	 * surcharges, which add up before being applied once, these modifiers
184	 * COMPOUND: each applies to the result of the last. A 20% discount followed
185	 * by a 10% surcharge is 100 -> 80 -> 88, not 100 -> 90.
186	 */
187	const applyCustomerModifiers = (
188	  price: number,
189	  customer: Customer,
190	  isFirstContract: boolean,
191	): number => {
192	  const afterLoyalty = adjustByPercent(
193	    price,
194	    percentWhen(isLongStanding(customer), LOYALTY_DISCOUNT_PERCENT),
195	  );
196	
197	  return adjustByPercent(afterLoyalty, contractPercentFor(isFirstContract));
198	};
199	
200	/**
201	 * The premium pipeline, in the order the spec states it: price the items,
202	 * apply the customer's modifiers, round, then add the processing fee last.
203	 */
204	const quotePremium = (
205	  items: InsuredItem[],
206	  customer: Customer,
207	  isFirstContract: boolean,
208	): QuoteResult => ({
209	  premium:
210	    roundInMHPCOsFavor(
211	      applyCustomerModifiers(priceItems(items), customer, isFirstContract),
212	    ) + PROCESSING_FEE,
213	});
214	
215	/**
216	 * Approximates "is this the customer's first contract?" by step position.
217	 *
218	 * This holds only while the first step is a quote. Now that claims interleave
219	 * with quotes, a scenario opening with a claim would make the quote that
220	 * follows look like a repeat contract. No test reaches that yet; when one
221	 * does, this has to count quote steps rather than trust the index.
222	 */
223	const isFirstContractAtStep = (stepIndex: number): boolean => stepIndex === 0;
224	
225	const DEDUCTIBLE = 100;
226	const CAP_MULTIPLE = 2;
227	
228	const insuranceSumOf = (items: InsuredItem[]): number =>
229	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
230	
231	/**
232	 * Stands in for a damage whose item type the policy does not list. Its bare
233	 * attributes trip no rate rule, so such a damage reimburses in full.
234	 */
235	const UNCOVERED_ITEM: InsuredItem = { type: "" };
236	
237	/** See SURCHARGEABLE_ENCHANTMENT_LEVEL — a different rule at a different level. */
238	const HALVING_ENCHANTMENT_LEVEL = 8;
239	const HALF = 0.5;
240	const IN_FULL = 1;
241	
242	const DRAGON_MATERIAL = "dragon";
243	
244	const isDragonMade = (item: InsuredItem): boolean =>
245	  item.material === DRAGON_MATERIAL;
246	
247	/** The mirror of attractsEnchantmentSurcharge, at the halving rule's level. */
248	const attractsEnchantmentHalving = (item: InsuredItem): boolean =>
249	  enchantmentOf(item) >= HALVING_ENCHANTMENT_LEVEL;
250	
251	/**
252	 * Damage to an item enchanted this far is only half reimbursed — unless it is
253	 * dragon-made, which the MHPCO always makes good in full whatever else is true
254	 * of the item. Dragon material is checked first because it overrides halving,
255	 * not the other way round.
256	 */
257	const reimbursementRateFor = (item: InsuredItem): number =>
258	  attractsEnchantmentHalving(item) && !isDragonMade(item) ? HALF : IN_FULL;
259	
260	/**
261	 * The damaged item's entry in the policy. A damage naming something the policy
262	 * does not cover reimburses in full — no rate rule can trip without an item to
263	 * read it from.
264	 */
265	const damagedItemIn = (
266	  damage: Damage,
267	  insuredItems: InsuredItem[],
268	): InsuredItem => insuredItems.find(isOfType(damage.itemType)) ?? UNCOVERED_ITEM;
269	
270	const reimbursableAmountOf = (
271	  damage: Damage,
272	  insuredItems: InsuredItem[],
273	): number =>
274	  damage.amount * reimbursementRateFor(damagedItemIn(damage, insuredItems));
275	
276	/** One incident is one deductible, so the damages are totalled before it applies. */
277	const totalDamageOf = (
278	  incident: Incident,
279	  insuredItems: InsuredItem[],
280	): number =>
281	  incident.damages.reduce(
282	    (sum, damage) => sum + reimbursableAmountOf(damage, insuredItems),
283	    0,
284	  );
285	
286	/** The MHPCO never pays a negative claim; below the deductible it pays nothing. */
287	const NO_PAYOUT = 0;
288	
289	/**
290	 * The customer bears the deductible, so only the damage above it is owed —
291	 * and an incident that stays within the deductible is owed nothing rather
292	 * than turning the shortfall into a debt.
293	 */
294	const payoutFor = (incident: Incident, insuredItems: InsuredItem[]): number =>
295	  Math.max(NO_PAYOUT, totalDamageOf(incident, insuredItems) - DEDUCTIBLE);
296	
297	const settleClaim = (
298	  incident: Incident,
299	  insuredItems: InsuredItem[],
300	  capBefore: number,
301	): ClaimResult => {
302	  const payout = Math.min(payoutFor(incident, insuredItems), capBefore);
303	
304	  return { payout, remainingCap: capBefore - payout };
305	};
306	
307	/** A policy's total cover: twice the insurance sum, shared by all its claims. */
308	const capOf = (insuredItems: InsuredItem[]): number =>
309	  CAP_MULTIPLE * insuranceSumOf(insuredItems);
310	
311	/**
312	 * A claim names the quote step it is made against; the items on that step are
313	 * the ones the policy covers.
314	 */
315	const itemsCoveredBy = (claim: ClaimStep, steps: Step[]): InsuredItem[] => {
316	  const policy = steps[claim.policy];
317	
318	  return policy.op === "quote" ? policy.items : [];
319	};
320	
321	/**
322	 * The running cover left on each policy, keyed by the quote step that opened
323	 * it. A policy absent from the ledger has not been claimed against yet, so its
324	 * remaining cover is still the full cap.
325	 */
326	type CapLedger = Map<number, number>;
327	
328	/**
329	 * Settles one claim against the ledger and draws the payout down from the
330	 * policy's remaining cover. This is the one step kind whose result depends on
331	 * the steps before it, so it is also the only one that writes to the ledger.
332	 */
333	const settleClaimAgainstLedger = (
334	  claim: ClaimStep,
335	  steps: Step[],
336	  remainingCaps: CapLedger,
337	): ClaimResult => {
338	  const insuredItems = itemsCoveredBy(claim, steps);
339	  const capBefore = remainingCaps.get(claim.policy) ?? capOf(insuredItems);
340	  const result = settleClaim(claim.incident, insuredItems, capBefore);
341	
342	  remainingCaps.set(claim.policy, result.remainingCap);
343	
344	  return result;
345	};
346	
347	/**
348	 * Works the scenario's steps in order, returning one result per step.
349	 *
350	 * The traversal is a `for...of` rather than a `map` because it is genuinely
351	 * order-dependent: each claim draws down a cap that later claims on the same
352	 * policy read back. `map` would compute the same answers — it runs
353	 * left-to-right — but it advertises an independent per-element transform, and
354	 * this is not one. The loop states the sequencing the cap ledger relies on.
355	 */
356	export const runScenario = ({
357	  customer,
358	  steps,
359	}: Scenario): ScenarioResults => {
360	  const remainingCaps: CapLedger = new Map();
361	  const results: StepResult[] = [];
362	
363	  for (const [stepIndex, step] of steps.entries()) {
364	    results.push(
365	      step.op === "quote"
366	        ? quotePremium(step.items, customer, isFirstContractAtStep(stepIndex))
367	        : settleClaimAgainstLedger(step, steps, remainingCaps),
368	    );
369	  }
370	
371	  return { results };
372	};
