/** The MHPCO never pays a negative claim; below the deductible it pays nothing. */
const NO_PAYOUT = 0;

/**
 * The customer bears the deductible, so only the damage above it is owed —
 * and an incident that stays within the deductible is owed nothing rather
 * than turning the shortfall into a debt.
 */
const payoutFor = (incident: Incident, insuredItems: InsuredItem[]): number =>
  Math.max(NO_PAYOUT, totalDamageOf(incident, insuredItems) - DEDUCTIBLE);

const settleClaim = (
  incident: Incident,
  insuredItems: InsuredItem[],
  capBefore: number,
): ClaimResult => {
  const payout = Math.min(payoutFor(incident, insuredItems), capBefore);

  return { payout, remainingCap: capBefore - payout };
};

